/* eslint-disable */
// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, spring, interpolate, random } from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadLilita = makeLoadFont('LilitaOne');

// Library: none — native interpolate/spring/svg with perfectly stacked z-layers for 3D

const { fontFamily: lilitaFamily } = loadLilita();



export type ComponentNameProps = Record<string, any>;

const ROCK_PATH = "M-20,-10 L-10,-25 L15,-15 L25,5 L10,25 L-15,20 Z";
const ROCK_INNER_PATH = "M-20,-10 L-10,-25 L15,-15 L5,0 Z";

const ComponentName: React.FC<ComponentNameProps> = ({
  line1 = "LAWYER REACTS",
  line2 = "TO A STORE ROOF",
  line3 = "CAVING IN",
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 5,
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();
  const s = Math.min(width, height) / 1080;
  const cx = width / 2;
  const cy = height / 2;

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Layout Calculations
  const lines = [line1, line2, line3];
  const fontSizes = [140 * s, 120 * s, 170 * s];
  const yPositions = [cy - 110 * s, cy + 10 * s, cy + 150 * s];
  const originYs = yPositions.map((y, i) => y - fontSizes[i] * 0.3);

  // Animation Springs & Interpolations
  const getScale = (idx: number) => spring({
    frame: frame - (idx * 5),
    fps,
    config: { damping: 11, stiffness: 140, mass: 0.7 }
  });
  const scales = [getScale(0), getScale(1), getScale(2)];

  const getRotation = (idx: number) => {
    const pFrame = frame - (idx * 5);
    return interpolate(
      pFrame,
      [0, 8, 25],
      [idx === 1 ? -15 : 15, idx === 1 ? 4 : -4, 0],
      { extrapolateRight: "clamp", extrapolateLeft: "clamp" }
    );
  };
  const rotations = [getRotation(0), getRotation(1), getRotation(2)];

  // Continuous subtle float
  const floatY = Math.sin(frame / 20) * 8 * s;
  const floatRot = Math.cos(frame / 30) * 1;

  // Transform generators
  const getTransform = (i: number) => `translate(${cx}, ${originYs[i]}) rotate(${rotations[i]}) scale(${scales[i]}) translate(${-cx}, ${-originYs[i]})`;
  const getRockTransform = (r: { dx: number, dy: number, size: number, lineIdx: number }) => {
    return getTransform(r.lineIdx) + ` translate(${cx + r.dx}, ${cy + r.dy}) scale(${r.size})`;
  };

  // Static Elements
  const ROCKS = [
    { dx: -450 * s, dy: -80 * s, r: 15, size: 1.5 * s, lineIdx: 0 },
    { dx: 430 * s, dy: -50 * s, r: 45, size: 1.2 * s, lineIdx: 0 },
    { dx: -480 * s, dy: 20 * s, r: -30, size: 1 * s, lineIdx: 1 },
    { dx: 460 * s, dy: 30 * s, r: 10, size: 0.8 * s, lineIdx: 1 },
    { dx: -150 * s, dy: 180 * s, r: -20, size: 1 * s, lineIdx: 2 },
    { dx: 50 * s, dy: 190 * s, r: 20, size: 1.3 * s, lineIdx: 2 },
    { dx: 250 * s, dy: 180 * s, r: -15, size: 0.9 * s, lineIdx: 2 },
  ];

  const CRACKS_DATA = [
    { d: `M ${cx + 120 * s} ${yPositions[0] - 60 * s} l -20 30 l 15 25 l -10 30`, lineIdx: 0 },
    { d: `M ${cx - 420 * s} ${yPositions[0] - 40 * s} l 30 20 l -10 30`, lineIdx: 0 },
    { d: `M ${cx - 280 * s} ${yPositions[2] - 30 * s} l 25 -30 l 5 -25 l 20 -20`, lineIdx: 2 },
    { d: `M ${cx + 340 * s} ${yPositions[2] - 10 * s} l -20 -30 l -30 -10`, lineIdx: 2 }
  ];

  // Dynamic Elements
  const generateDebris = () => {
    const items = [];
    for (let i = 0; i < 15; i++) {
      const angle = (i / 15) * Math.PI * 2 + random(i) * 0.5;
      const speed = 400 + random(i + 10) * 700;
      const delay = Math.floor(random(i + 20) * 8);
      items.push({ id: i, angle, speed, delay, size: 0.5 + random(i + 30) * 0.7 });
    }
    return items;
  };
  const debrisList = generateDebris();

  // Layer Offsets & Thickness
  const OUTLINE = 40 * s; 
  const ORANGE_OUTLINE = 10 * s; 
  const EXTRUSION_Y = 15 * s;
  const SHADOW_Y = 35 * s;

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: lilitaFamily, transition: "none" }}>
      <svg width={width} height={height} style={{ overflow: "visible", transition: "none" }}>
        <defs>
          <linearGradient id="bubbleGrad" x1="0" y1="0" x2="0" y2="1">
            <stop offset="0%" stopColor="#ffffff" />
            <stop offset="12%" stopColor="#fef08a" />
            <stop offset="30%" stopColor="#facc15" />
            <stop offset="70%" stopColor="#eab308" />
            <stop offset="90%" stopColor="#ca8a04" />
            <stop offset="100%" stopColor="#713f12" />
          </linearGradient>

          <clipPath id="textClip">
            {lines.map((txt, i) => (
              <text key={`tc_${i}`} x={cx} y={yPositions[i]} fontSize={fontSizes[i]} transform={getTransform(i)} textAnchor="middle" style={{ transition: "none" }}>{txt}</text>
            ))}
          </clipPath>
        </defs>

        <g transform={`translate(${cx}, ${cy}) translateY(${floatY}) rotate(${floatRot}) translate(${-cx}, ${-cy})`} style={{ transition: "none" }}>

          {/* Dynamic Falling Debris Layer */}
          <g style={{ transition: "none" }}>
            {debrisList.map(p => {
              const pFrame = frame - p.delay;
              const time = Math.max(0, pFrame) / fps;
              const vx = Math.cos(p.angle) * p.speed * s;
              const vy0 = Math.sin(p.angle) * p.speed * s - 400 * s;
              const gravity = 1800 * s;

              const x = cx + vx * time;
              const y = cy + vy0 * time + 0.5 * gravity * time * time;
              const rot = time * 400 * (p.id % 2 === 0 ? 1 : -1);
              const pScale = interpolate(pFrame, [0, 8], [0, p.size], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });

              const op = interpolate(y, [cy + 300 * s, cy + 800 * s], [1, 0], { extrapolateRight: "clamp", extrapolateLeft: "clamp" });
              const finalOpacity = pFrame > 0 ? op : 0;

              return (
                <g key={p.id} transform={`translate(${x}, ${y}) rotate(${rot}) scale(${pScale})`} opacity={finalOpacity} style={{ transition: "none" }}>
                  <path d={ROCK_PATH} stroke="black" strokeWidth={15 * s} fill="#4b5563" strokeLinejoin="round" />
                  <path d={ROCK_INNER_PATH} fill="#9ca3af" />
                </g>
              );
            })}
          </g>

          {/* Layer 0: Subtle Glow */}
          <g>
            {lines.map((txt, i) => (
              <text key={`tg_${i}`} x={cx} y={yPositions[i]} fontSize={fontSizes[i]} transform={getTransform(i)} textAnchor="middle" stroke="#facc15" strokeWidth={100 * s} fill="none" style={{ filter: `blur(${40 * s}px)`, opacity: 0.4, transition: "none" }}>{txt}</text>
            ))}
          </g>

          {/* Layer 1: Deep Drop Shadow */}
          <g transform={`translate(0, ${SHADOW_Y})`}>
            {ROCKS.map((r, i) => <path key={`rs_${i}`} d={ROCK_PATH} transform={getRockTransform(r)} stroke="black" strokeWidth={OUTLINE} fill="black" strokeLinejoin="round" />)}
            {lines.map((txt, i) => <text key={`ts_${i}`} x={cx} y={yPositions[i]} fontSize={fontSizes[i]} transform={getTransform(i)} textAnchor="middle" stroke="black" strokeWidth={OUTLINE + 20 * s} fill="black" strokeLinejoin="round" style={{ transition: "none" }}>{txt}</text>)}
          </g>

          {/* Layer 2: Extrusion Black Base */}
          <g transform={`translate(0, ${EXTRUSION_Y})`}>
            {ROCKS.map((r, i) => <path key={`ro_${i}`} d={ROCK_PATH} transform={getRockTransform(r)} stroke="black" strokeWidth={OUTLINE} fill="black" strokeLinejoin="round" />)}
            {lines.map((txt, i) => <text key={`to_${i}`} x={cx} y={yPositions[i]} fontSize={fontSizes[i]} transform={getTransform(i)} textAnchor="middle" stroke="black" strokeWidth={OUTLINE + 10 * s} fill="black" strokeLinejoin="round" style={{ transition: "none" }}>{txt}</text>)}
          </g>

          {/* Layer 3: Extrusion Dark Orange */}
          <g transform={`translate(0, ${EXTRUSION_Y})`}>
            {ROCKS.map((r, i) => <path key={`rb_${i}`} d={ROCK_PATH} transform={getRockTransform(r)} stroke="#374151" strokeWidth={ORANGE_OUTLINE} fill="#374151" strokeLinejoin="round" />)}
            {lines.map((txt, i) => <text key={`tb_${i}`} x={cx} y={yPositions[i]} fontSize={fontSizes[i]} transform={getTransform(i)} textAnchor="middle" stroke="#b45309" strokeWidth={ORANGE_OUTLINE + 10 * s} fill="#b45309" strokeLinejoin="round" style={{ transition: "none" }}>{txt}</text>)}
          </g>

          {/* Layer 4: Top Face Black Outline */}
          <g>
            {ROCKS.map((r, i) => <path key={`rfo_${i}`} d={ROCK_PATH} transform={getRockTransform(r)} stroke="black" strokeWidth={OUTLINE} fill="black" strokeLinejoin="round" />)}
            {lines.map((txt, i) => <text key={`tfo_${i}`} x={cx} y={yPositions[i]} fontSize={fontSizes[i]} transform={getTransform(i)} textAnchor="middle" stroke="black" strokeWidth={OUTLINE} fill="black" strokeLinejoin="round" style={{ transition: "none" }}>{txt}</text>)}
          </g>

          {/* Layer 5: Main Gradient Faces */}
          <g>
            {ROCKS.map((r, i) => (
              <g key={`rf_${i}`} transform={getRockTransform(r)} style={{ transition: "none" }}>
                <path d={ROCK_PATH} fill="#4b5563" />
                <path d={ROCK_INNER_PATH} fill="#9ca3af" />
              </g>
            ))}
            {lines.map((txt, i) => (
              <text key={`tf_${i}`} x={cx} y={yPositions[i]} fontSize={fontSizes[i]} transform={getTransform(i)} textAnchor="middle" fill="url(#bubbleGrad)" style={{ transition: "none" }}>{txt}</text>
            ))}
          </g>

          {/* Layer 6: Cracks perfectly clipped to the letters */}
          <g clipPath="url(#textClip)">
            {CRACKS_DATA.map((crack, i) => (
              <path key={`cr_${i}`} d={crack.d} transform={getTransform(crack.lineIdx)} stroke="black" strokeWidth={6 * s} fill="none" strokeLinecap="round" strokeLinejoin="round" style={{ transition: "none" }} />
            ))}
          </g>

        </g>
      </svg>
    </AbsoluteFill>
  );
};

export default ComponentName;